CREATE OR REPLACE FUNCTION log_interaction_metrics()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO interactionmetrics (intmetkey, interaction_behavior)
    VALUES (NEW.intkey, 
        jsonb_build_object(
            'scroll', jsonb_build_object('depth', 0, 'speed', 0.0, 'percentage', 0),
            'exit_type', 'Natural',
            'conversion', jsonb_build_object('value', 0, 'status', 'None'),
            'time_spent', jsonb_build_object('viewport_time', 0, 'attention_time', 0, 'reading_seconds', 0, 'duration_seconds', 0),
            'next_action', 'None',
            'bounce_status', 'No',
            'click_seconds', 0
        )
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_log_interaction_metrics
AFTER INSERT ON interactions
FOR EACH ROW
EXECUTE FUNCTION log_interaction_metrics();

CREATE OR REPLACE FUNCTION log_interaction_metrics()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.inttype <> 'Hover' THEN
        INSERT INTO interactionmetrics (intmetkey, interaction_behavior)
        VALUES (NEW.intkey, 
            jsonb_build_object(
                'scroll', jsonb_build_object('depth', 0, 'speed', 0.0, 'percentage', 0),
                'exit_type', 'Natural',
                'conversion', jsonb_build_object('value', 0, 'status', 'None'),
                'time_spent', jsonb_build_object('viewport_time', 0, 'attention_time', 0, 'reading_seconds', 0, 'duration_seconds', 0),
                'next_action', 'None',
                'bounce_status', 'No',
                'click_seconds', 0
            )
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_log_interaction_metrics ON interactions;

CREATE TRIGGER trg_log_interaction_metrics
AFTER INSERT ON interactions
FOR EACH ROW
EXECUTE FUNCTION log_interaction_metrics();
